def lines(chunks):
    out=[]; buf=''
    for chunk in chunks:
        buf+=chunk
        while '\n' in buf:
            line,buf=buf.split('\n',1)
            out.append(line[:-1] if line.endswith('\r') else line)
    if buf: out.append(buf)
    return out

